function buildSearchIndex(lang) {
  const el = lang === "el";
  const items = [];
  const push = (kind, tab, target, title, sub, body, altName) =>
    items.push({
      kind, tab, target, title, sub,
      names: [norm(title)].concat(altName ? [norm(altName)] : []),
      hay: norm(title + " " + (altName || "") + " " + (sub || "") + " " + (body || ""))
    });

  for (const d of DRUGS) {
    const doses = (d.doses || []).map((x) => (el ? x.el : x.en) + " " + (x.fixed || "") + " " + (x.unit || "")).join(" ");
    // synEl carries the Greek name so a Greek user finds the drug by typing Greek.
    push("drug", "meds", d.id, d.name, el ? "\u03A6\u03AC\u03C1\u03BC\u03B1\u03BA\u03BF" : "Drug",
      doses + " " + ((el ? d.notesEl : d.notesEn) || ""), d.synEl);
  }
  for (const c of CHECKLISTS) {
    push("list", "lists", c.id, el ? c.titleEl : c.titleEn, el ? "\u0395\u03C0\u03B5\u03AF\u03B3\u03BF\u03BD" : "Emergency checklist",
      (el ? c.stepsEl : c.stepsEn).join(" "));
  }
  for (const s of TOOL_SECTIONS) {
    // kw exposes what the card actually covers; its body is rendered at runtime
    // and so cannot be indexed directly.
    push("tool", "tools", s.id, el ? s.el : s.en, el ? "\u0395\u03C1\u03B3\u03B1\u03BB\u03B5\u03AF\u03BF" : "Tool", s.kw || "");
  }
  for (const s of SCORES) {
    push("score", "tools", "scores", s.name, el ? "\u039A\u03BB\u03AF\u03BC\u03B1\u03BA\u03B1" : "Risk score",
      s.items.map((i) => i[lang] || "").join(" "));
  }
  for (const g of GUIDELINES) {
    const secs = (el ? g.secEl : g.secEn) || [];
    push("guide", "tools", "guidelines", el ? g.el : g.en, el ? "\u039F\u03B4\u03B7\u03B3\u03AF\u03B1" : "Guideline",
      secs.map((s) => s.h + " " + (s.items || []).join(" ")).join(" "));
  }
  return items;
}

const KIND_STYLE = {
  drug:  { bg: S.tintInfo, fg: S.teal },
  list:  { bg: S.tintDanger, fg: S.tintDangerFg },
  tool:  { bg: S.tintOk, fg: S.tintOkFg },
  score: { bg: S.tintWarn, fg: S.tintWarnFg },
  guide: { bg: S.tintGuide, fg: S.tintGuideFg }
};

